const input = typeof query === 'string' ? { termo: query } : (query || {});
const termoRaw = (input.termo ?? input.query ?? '').toString().trim();
const termo = ['', 'todos', 'tudo', 'all', '*'].includes(termoRaw.toLowerCase()) ? '' : termoRaw;
const qs = termo ? { termo } : {};
const resp = await helpers.httpRequest({
  method: 'GET',
  url: 'http://chatbot-api:8000/v1/estoque/buscar',
  qs,
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
  json: true,
});

// Uma busca específica com resultado único preserva os dados internos da moto
// (static n8n + CRM) — simular1 sobrevive a restart do n8n.
try {
  const veiculos = Array.isArray(resp?.veiculos) ? resp.veiculos : [];
  const origem = $('Extrair1').first().json;
  const telefone = String(origem.telefone || '').replace(/\D/g, '');
  const instance = String(origem.instance || '').trim();
  if (termo && telefone && veiculos.length === 1) {
    const item = veiculos[0] || {};
    const escolhida = {
      id: String(item.id || ''),
      placa: String(item.placa || '').trim().toUpperCase(),
      valor: Number(item.preco),
      categoria: String(item.tipo || item.categoria || 'moto').toLowerCase(),
      interesse: [item.marca, item.modelo, item.versao, item.ano_modelo || item.ano]
        .filter(Boolean).join(' '),
    };
    try {
      const estado = $getWorkflowStaticData('global');
      estado['moto-escolhida:' + telefone] = escolhida;
    } catch (_) {}
    // Persistência no CRM (fonte de verdade se static data sumir).
    try {
      await helpers.httpRequest({
        method: 'POST',
        url: 'http://chatbot-api:8000/v1/operacao/moto-escolhida',
        headers: {
          Authorization: 'Bearer __CHATBOT_TOKEN__',
          'Content-Type': 'application/json',
        },
        body: { telefone, instance: instance || null, ...escolhida },
        json: true,
        timeout: 8000,
      });
    } catch (_) {}
  }
} catch (_) {}

// Listagem ampla ou ambígua invalida seleção anterior (static + CRM).
try {
  const veiculosTeste = Array.isArray(resp?.veiculos) ? resp.veiculos : [];
  const origemTeste = $('Extrair1').first().json;
  const telefoneTeste = String(origemTeste.telefone || '').replace(/\D/g, '');
  const instanceTeste = String(origemTeste.instance || '').trim();
  if (telefoneTeste && !(termo && veiculosTeste.length === 1)) {
    try {
      const estadoTeste = $getWorkflowStaticData('global');
      delete estadoTeste['moto-escolhida:' + telefoneTeste];
    } catch (_) {}
    try {
      await helpers.httpRequest({
        method: 'POST',
        url: 'http://chatbot-api:8000/v1/operacao/moto-escolhida',
        headers: {
          Authorization: 'Bearer __CHATBOT_TOKEN__',
          'Content-Type': 'application/json',
        },
        body: { telefone: telefoneTeste, instance: instanceTeste || null },
        json: true,
        timeout: 8000,
      });
    } catch (_) {}
  }
} catch (_) {}

return JSON.stringify(resp);

const input = typeof query === 'string' ? {} : (query || {});
const origem = $('Extrair1').first().json;
const instance = String(origem.instance || '').trim();
const telefone = String(origem.telefone || '').replace(/\D/g, '');
const cpf = String(input.cpf || '').trim();
const cpfDigitos = cpf.replace(/\D/g, '');
// CPF no histórico fica mascarado (*********XX). Recupera o valor capturado
// na conversa (webhook cpf_cliente → static data) se a tool recebeu lixo/máscara.
let cpfDigitosEfetivo = cpfDigitos;
if (cpfDigitosEfetivo.length !== 11 || /\*/.test(cpf)) {
  try {
    const estadoCpf = $getWorkflowStaticData('global');
    const guardado = String(estadoCpf['cpf-cliente:' + telefone] || '').replace(/\D/g, '');
    if (guardado.length === 11) cpfDigitosEfetivo = guardado;
  } catch (_) {}
  if (cpfDigitosEfetivo.length !== 11) {
    const doOrigem = String(origem.cpfCliente || origem.cpf_cliente || '').replace(/\D/g, '');
    if (doOrigem.length === 11) cpfDigitosEfetivo = doOrigem;
  }
}

const nascimentoRaw = String(input.nascimento || '').trim();
const dataBr = nascimentoRaw.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);
const nascimento = dataBr ? dataBr[3] + '-' + dataBr[2] + '-' + dataBr[1] : nascimentoRaw;
let placa = String(input.placa || '').trim().toUpperCase();
const entrada = Number(input.entrada);
let valor = Number(input.valor);
let categoria = String(input.categoria || '').trim().toLowerCase();
let interesse = String(input.interesse || '').trim();
const temCnhRaw = String(input.tem_cnh || '').trim().toLowerCase();

function aplicarEscolhida(escolhida) {
  if (!escolhida || typeof escolhida !== 'object') return;
  if (!placa) placa = String(escolhida.placa || '').trim().toUpperCase();
  if (!(Number.isFinite(valor) && valor > 0)) valor = Number(escolhida.valor);
  if (!categoria) categoria = String(escolhida.categoria || 'moto').toLowerCase();
  if (!interesse) interesse = String(escolhida.interesse || '').trim();
}

// 1) static n8n  2) registrar/webhook (CRM)  3) reconsulta estoque por interesse
try {
  const estado = $getWorkflowStaticData('global');
  aplicarEscolhida(estado['moto-escolhida:' + telefone] || null);
} catch (_) {}
if (!(placa || (Number.isFinite(valor) && valor > 0))) {
  aplicarEscolhida(origem.motoEscolhida || origem.moto_escolhida || null);
}
if (!(placa || (Number.isFinite(valor) && valor > 0))) {
  const termoBusca = interesse || String(input.interesse || '').trim();
  if (termoBusca) {
    try {
      const respEst = await helpers.httpRequest({
        method: 'GET',
        url: 'http://chatbot-api:8000/v1/estoque/buscar',
        qs: { termo: termoBusca },
        headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
        json: true,
        timeout: 10000,
      });
      const veiculos = Array.isArray(respEst?.veiculos) ? respEst.veiculos : [];
      if (veiculos.length === 1) {
        const item = veiculos[0] || {};
        const escolhida = {
          id: String(item.id || ''),
          placa: String(item.placa || '').trim().toUpperCase(),
          valor: Number(item.preco),
          categoria: String(item.tipo || item.categoria || 'moto').toLowerCase(),
          interesse: [item.marca, item.modelo, item.versao, item.ano_modelo || item.ano]
            .filter(Boolean).join(' ') || termoBusca,
        };
        aplicarEscolhida(escolhida);
        try {
          const st = $getWorkflowStaticData('global');
          st['moto-escolhida:' + telefone] = escolhida;
        } catch (_) {}
      }
    } catch (_) {}
  }
}

const temValorEstoque = Number.isFinite(valor) && valor > 0;
const categoriaValida = categoria === 'moto' || categoria === 'carro';
const temVeiculoInterno = Boolean(placa) || (temValorEstoque && categoriaValida);

if (!temVeiculoInterno) {
  return JSON.stringify({
    ok: false,
    precisa_escolher_moto: true,
    mensagem: 'a moto ainda não foi escolhida. volte ao catálogo e pergunte somente qual moto o cliente quer conhecer melhor. não fale em simulação e não peça cpf, nascimento, entrada ou placa agora. NÃO diga certinho nem que vai preparar simulação.',
  });
}

// Normaliza CNH para sim/não objetivo (bloqueia se ambíguo).
function normalizarCnh(valor) {
  let raw = String(valor || '').trim().toLowerCase();
  raw = raw.replace(/[ãáàâ]/g, 'a').replace(/[éê]/g, 'e').replace(/[óô]/g, 'o')
    .replace(/[.?!"]/g, '').trim();
  if (['s', 'sim', 'ss', 'si', 'tenho', 'possuo', 'true', '1', 'yes', 'y'].includes(raw)) return 'sim';
  if (['n', 'nao', 'nn', 'no', 'nop', 'false', '0', 'nao tenho', 'nao possuo', 'sem cnh', 'sem'].includes(raw)) return 'nao';
  if (/^(sim|tenho|possuo)(\s+\w+){0,3}$/.test(raw) && !/\bnao\b/.test(raw)) return 'sim';
  if (/^(nao|no)(\s+\w+){0,3}$/.test(raw) || raw.startsWith('nao ')) return 'nao';
  return '';
}
const temCnhNorm = normalizarCnh(temCnhRaw);

// Idade civil a partir de YYYY-MM-DD ou DD/MM/AAAA (gate local; backend reforça).
function idadeDeNascimento(nascIsoOuBr) {
  const mIso = String(nascIsoOuBr || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const mBr = String(nascIsoOuBr || '').match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);
  let y, mo, d;
  if (mIso) { y = +mIso[1]; mo = +mIso[2]; d = +mIso[3]; }
  else if (mBr) { d = +mBr[1]; mo = +mBr[2]; y = +mBr[3]; }
  else return null;
  const nasc = new Date(Date.UTC(y, mo - 1, d));
  if (Number.isNaN(nasc.getTime())) return null;
  const hoje = new Date();
  let idade = hoje.getUTCFullYear() - y;
  const mNow = hoje.getUTCMonth() + 1;
  const dNow = hoje.getUTCDate();
  if (mNow < mo || (mNow === mo && dNow < d)) idade -= 1;
  return idade;
}

const faltando = [];
if (!telefone) faltando.push('telefone interno');
if (cpfDigitosEfetivo.length !== 11) faltando.push('cpf');
if (!nascimento) faltando.push('data de nascimento');
if (!temCnhNorm) faltando.push('cnh');
if (faltando.length) {
  return JSON.stringify({
    ok: false,
    faltando,
    mensagem: faltando.includes('cnh')
      ? 'confirme claramente se o cliente tem CNH. peça resposta objetiva: sim ou não. “não” também vale e a simulação segue. insista com educação só se a resposta for vaga. NÃO diga certinho nem que vai encaminhar pro setor enquanto a CNH não estiver confirmada. NUNCA diga que sem CNH não dá para simular.'
      : 'peça somente os campos listados em faltando. nunca peça novamente um dado que já chegou na mensagem atual ou no histórico. NÃO diga certinho nem que vai preparar simulação enquanto faltar dado.',
  });
}

const idade = idadeDeNascimento(nascimento);
if (idade !== null && idade < 18) {
  return JSON.stringify({
    ok: true,
    bloqueado: true,
    motivo_bloqueio: 'menor_de_idade',
    simulacao_humana_solicitada: false,
    mensagem: 'No momento, não é possível liberar financiamento para menores de 18 anos. Quando você atingir a maioridade, poderemos realizar uma nova simulação para você.',
  });
}

if (!interesse) interesse = 'simulação de financiamento';
const entradaValida = Number.isFinite(entrada) && entrada >= 0 ? entrada : null;
const bodyMotor = { cpf: cpfDigitosEfetivo, nascimento, telefone };
if (entradaValida !== null) bodyMotor.entrada = entradaValida;
if (placa) {
  bodyMotor.placa = placa;
} else {
  bodyMotor.valor = valor;
  bodyMotor.categoria = categoria;
}

const headers = { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' };
const mensagemId = String(origem.providerMessageId || '').trim();
if (!mensagemId) {
  return JSON.stringify({
    ok: false,
    mensagem: 'não foi possível registrar a simulação agora. peça para o cliente reenviar a última mensagem. NÃO diga certinho nem que a simulação foi preparada.',
  });
}
headers['Idempotency-Key'] = mensagemId;

try {
  await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/simulacoes/solicitar',
    headers,
    body: bodyMotor,
    json: true,
    timeout: 10000,
  });
} catch (_) {}

const nomeRaw = String(origem.pushName || origem.nomeWhatsapp || '').trim();
const nomeGenerico = !nomeRaw || ['cliente', 'customer', 'user', 'usuario'].includes(nomeRaw.toLowerCase());
const bodyHumano = {
  telefone,
  interesse,
  tem_cnh: temCnhNorm,
  instance: instance || null,
  cpf: cpfDigitosEfetivo,
  nascimento: nascimento || null,
  cpf_recebido: true,
  nascimento_recebido: true,
  fallback_temporario: false,
  entrada: Number.isFinite(entrada) && entrada >= 0 ? entrada : null,
};
if (!nomeGenerico) bodyHumano.nome = nomeRaw;

try {
  const resp = await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/operacao/solicitacoes-simulacao-humana',
    headers,
    body: bodyHumano,
    json: true,
    timeout: 15000,
  });
  if (resp && resp.bloqueado === true) {
    return JSON.stringify({
      ok: resp.ok === true,
      bloqueado: true,
      motivo_bloqueio: resp.motivo_bloqueio || 'bloqueado',
      faltando: resp.faltando || undefined,
      simulacao_humana_solicitada: false,
      mensagem: resp.mensagem || 'não foi possível seguir com a simulação agora.',
    });
  }
  if (resp && resp.ok === true && resp.simulacao_humana_solicitada === true) {
    return JSON.stringify({
      ok: true,
      simulacao_humana_solicitada: true,
      duplicada: Boolean(resp.duplicada),
      mensagem: resp.mensagem || 'certo, já tenho seus dados. vou encaminhar pro setor de simulação e te retorno por aqui. atendemos das 8h30 às 18h; fora desse horário, respondo no próximo dia útil.',
    });
  }
  if (resp && resp.ok === false && Array.isArray(resp.faltando) && resp.faltando.length) {
    return JSON.stringify({
      ok: false,
      faltando: resp.faltando,
      motivo_bloqueio: resp.motivo_bloqueio || undefined,
      mensagem: resp.mensagem || 'peça somente os campos listados em faltando.',
    });
  }
  return JSON.stringify({
    ok: false,
    mensagem: 'não consegui registrar a simulação agora. peça os dados de novo em instantes. NÃO diga certinho nem que a simulação foi preparada.',
  });
} catch (_) {
  return JSON.stringify({
    ok: false,
    mensagem: 'não consegui registrar a simulação agora. peça os dados de novo em instantes. NÃO diga certinho nem que a simulação foi preparada.',
  });
