  input.interesse || anterior?.interesse || linhaAnuncio || origem.anuncioTitulo || ''
).trim().slice(0, 160);
if (!interesse) {
  return JSON.stringify({
    ok: false,
    fallback_temporario: true,
    pode_oferecer_fotos: false,
    mensagem: 'pergunte somente qual moto o cliente quer simular.',
  });
}
if (estado) estado[chave] = { interesse, atualizado_em: Date.now() };

if (input.confirmar_simulacao !== true) {
  return JSON.stringify({
