    const g = String(st['cpf-cliente:' + telefone] || '').replace(/\D/g, '');
    if (g.length === 11) cpfDigitos = g;
  } catch (_) {}
  if (cpfDigitos.length !== 11) {
    const o = String(origem.cpfCliente || origem.cpf_cliente || '').replace(/\D/g, '');
    if (o.length === 11) cpfDigitos = o;
  }
