if (!mensagemId) {
  return JSON.stringify({
    ok: false,
    fallback_temporario: true,
    pode_oferecer_fotos: false,
    mensagem: 'não foi possível registrar a simulação agora. peça para o cliente reenviar a última mensagem.',
