  });
  if (estado) delete estado[chave];
  if (resp && resp.bloqueado === true) {
    return JSON.stringify({
      ok: resp.ok === true,
      fallback_temporario: true,
      bloqueado: true,
      motivo_bloqueio: resp.motivo_bloqueio || 'bloqueado',
