    });
  }
  if (resp && resp.ok === false && Array.isArray(resp.faltando) && resp.faltando.length) {
    return JSON.stringify({
      ok: false,
      fallback_temporario: true,
      faltando: resp.faltando,
      motivo_bloqueio: resp.motivo_bloqueio || undefined,
      pode_oferecer_fotos: false,
      mensagem: resp.mensagem || 'peça somente os campos listados em faltando.',
    });
