  return JSON.stringify({
    ok: false,
    fallback_temporario: true,
    pode_oferecer_fotos: false,
    mensagem: 'não consegui registrar a simulação agora. peça os dados de novo em instantes.',
  });
} catch (_) {
  return JSON.stringify({
    ok: false,
    fallback_temporario: true,
