// Anti-ban itens 1+2: calcula o "delay" (ms) que a Evolution usa para
// (1) mostrar "digitando..." proporcional ao tamanho do texto e
// (2) espacar os envios da MESMA instancia (throttle global), evitando rajada.
// A Evolution segura a mensagem por 'delay' ms antes de enviar. Falha-fecha:
// qualquer erro cai so no typing e NUNCA bloqueia a resposta.
const rand = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
let inst = '';
try { inst = String($('Extrair1').first().json.instance || ''); } catch (_) {}
let st = null;
try { st = $getWorkflowStaticData('global'); } catch (_) {}
const chave = 'throttle-next:' + inst;
const TETO_FILA = 12000;   // nunca segura a fila alem disto (degrada agrupando)
const TETO_TOTAL = 16000;  // teto final p/ nao estourar timeout do HTTP node
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const texto = String(j.output || '');
  // typing: ~45ms/char (teto 4s) + jitter humano 0.8-2.5s.
  const typing = Math.min(texto.length * 45, 4000) + rand(800, 2500);
  let delay = typing;
  if (st) {
    try {
      const now = Date.now();
      const prox = Number(st[chave] || 0);
      const inicio = Math.max(now, prox);
      let espera = inicio - now;
      if (espera > TETO_FILA) espera = TETO_FILA;
      delay = espera + typing;
      st[chave] = inicio + rand(3000, 6000); // reserva o proximo slot (3-6s)
    } catch (_) {}
  }
  if (delay > TETO_TOTAL) delay = TETO_TOTAL;
  out.push({ json: { ...j, __delayAntiBan: Math.round(delay) } });
}
return out;

// Modo 2: o handoff NAO avisa grupo (nao existe grupo) — ele abre o rodizio.
// Terceiro gatilho da spec 5.2, "cliente pediu humano". Sem CPF/nascimento de
// proposito: a 5.2 diz que este gatilho pode vir antes da simulacao.
const input = typeof query === 'string' ? { motivo: query } : (query || {});
const origem = $('Extrair1').first().json;
const telefone = String(origem.telefone || '').replace(/\D/g, '');
const motivo = String(input.motivo || 'cliente pediu atendimento humano').trim().slice(0, 120);
if (!telefone) return JSON.stringify({ mensagem: 'nao consegui identificar a conversa para encaminhar.' });

try {
  await helpers.httpRequest({
    method: 'PATCH',
    url: 'http://chatbot-api:8000/v1/conversas/' + encodeURIComponent(telefone) + '/estado',
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body: { bot_ativo: false, instance: String(origem.instance || '') || null },
    json: true,
    timeout: 10000,
  });
} catch (_) {
  return JSON.stringify({ mensagem: 'nao consegui encaminhar agora. tente novamente em alguns instantes.' });
}

try {
  const r = await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/operacao/handoff-humano',
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body: { telefone, motivo },
